pm.test('Response carries jobId, statusUrl, submitted', function () {
    const body = pm.response.json();
    pm.expect(body.jobId).to.be.a('string').and.not.empty;
    pm.expect(body.statusUrl).to.eql('/api/v1/jobs/' + body.jobId + '/status');
    pm.expect(body.submitted).to.eql(1);
});

